using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

public class PauseMenuController : MonoBehaviour
{
    [SerializeField] private CanvasGroup pauseMenuPanel;
    [SerializeField] private Button resumeButton;
    [SerializeField] private Button quitButton;
    [SerializeField] private Button mainMenuButton;
    [SerializeField] private KeyCode pauseKey = KeyCode.Escape;

    private bool isPaused = false;

    private void Start()
    {
        // Set up button listeners
        if (resumeButton != null)
            resumeButton.onClick.AddListener(Resume);
        if (quitButton != null)
            quitButton.onClick.AddListener(QuitGame);
        if (mainMenuButton != null)
            mainMenuButton.onClick.AddListener(GoToMainMenu);

        // Hide menu initially
        if (pauseMenuPanel != null)
        {
            pauseMenuPanel.alpha = 0f;
            pauseMenuPanel.interactable = false;
            pauseMenuPanel.blocksRaycasts = false;
        }
    }

    private void Update()
    {
        if (Input.GetKeyDown(pauseKey))
        {
            if (isPaused)
                Resume();
            else
                Pause();
        }
    }

    private void Pause()
    {
        isPaused = true;
        Time.timeScale = 0f; // Pause the game
        ShowMenu();
    }

    private void Resume()
    {
        isPaused = false;
        Time.timeScale = 1f; // Resume the game
        HideMenu();
    }

    private void ShowMenu()
    {
        if (pauseMenuPanel != null)
        {
            pauseMenuPanel.alpha = 1f;
            pauseMenuPanel.interactable = true;
            pauseMenuPanel.blocksRaycasts = true;
        }
    }

    private void HideMenu()
    {
        if (pauseMenuPanel != null)
        {
            pauseMenuPanel.alpha = 0f;
            pauseMenuPanel.interactable = false;
            pauseMenuPanel.blocksRaycasts = false;
        }
    }

    private void QuitGame()
    {
        Time.timeScale = 1f; // Resume time before quitting
        #if UNITY_EDITOR
            UnityEditor.EditorApplication.isPlaying = false;
        #else
            Application.Quit();
        #endif
    }

    private void GoToMainMenu()
    {
        Time.timeScale = 1f; // Resume time before loading scene
        SceneManager.LoadScene("Menu"); // Make sure your main menu scene is named "Menu"
    }
}

using UnityEngine;

public class PlacementManager : MonoBehaviour
{
    public static PlacementManager Instance;

    public LayerMask groundLayer;
    public Material ghostMaterial;
    public InventoryManager inventoryManager;

    public float rotationSpeed = 120f;

    private GameObject ghostObject;
    private InventoryItemData currentItem;
    private float currentRotationY;

    void Awake()
    {
        Instance = this;
    }

    void Update()
    {
        if (ghostObject == null) return;

        FollowMouse();
        HandleRotation();

        if (Input.GetMouseButtonDown(0))
            PlaceObject();

        if (Input.GetMouseButtonDown(1) || Input.GetKeyDown(KeyCode.Escape))
            CancelPlacement();
    }

    public void StartPlacement(InventoryItemData item)
    {
        CancelPlacement();

        currentItem = item;
        ghostObject = Instantiate(item.prefab3D);

        currentRotationY = 0;
        SetGhostMaterial(ghostObject);
    }

    void FollowMouse()
    {
        Ray ray = Camera.main.ScreenPointToRay(Input.mousePosition);

        if (Physics.Raycast(ray, out RaycastHit hit, 1000f, groundLayer))
        {
            ghostObject.transform.position = hit.point + Vector3.up * 0.0f;
        }
    }

    void HandleRotation()
    {
        if (Input.GetKey(KeyCode.Q))
            currentRotationY -= rotationSpeed * Time.deltaTime;

        if (Input.GetKey(KeyCode.E))
            currentRotationY += rotationSpeed * Time.deltaTime;

        ghostObject.transform.rotation = Quaternion.Euler(0, currentRotationY, 0);
    }

    void PlaceObject()
    {
        GameObject newObj = Instantiate(currentItem.prefab3D,
            ghostObject.transform.position,
            ghostObject.transform.rotation);

        // Add a component to store the prefab name for save/load
        FurniturePrefabReference prefabRef = newObj.AddComponent<FurniturePrefabReference>();
        prefabRef.prefabPath = currentItem.name; // Use the ScriptableObject name as the identifier

        // Register the placed object with the FurnitureSaveManager
        FurnitureSaveManager saveManager = FindObjectOfType<FurnitureSaveManager>();
        if (saveManager != null) {
            saveManager.activeFurniture.Add(newObj);
            Debug.Log("Added " + newObj.name + " to activeFurniture list");
        } else {
            Debug.LogWarning("FurnitureSaveManager not found in scene!");
        }

        CancelPlacement();
    }

    void CancelPlacement()
    {
        if (ghostObject != null)
            Destroy(ghostObject);

        ghostObject = null;
        currentItem = null;
    }

    void SetGhostMaterial(GameObject obj)
    {
        foreach (Renderer r in obj.GetComponentsInChildren<Renderer>())
            r.material = ghostMaterial;
    }
}

using UnityEngine;

public class PlacementManager : MonoBehaviour
{
    public static PlacementManager Instance;

    public LayerMask groundLayer;
    public Material ghostMaterial;
    public InventoryManager inventoryManager;

    public float rotationSpeed = 120f;

    private GameObject ghostObject;
    private InventoryItemData currentItem;
    private GameObject currentPrefab;
    private float currentRotationY;

    void Awake()
    {
        Instance = this;
    }

    void Update()
    {
        if (ghostObject == null) return;

        FollowMouse();
        HandleRotation();

        if (Input.GetMouseButtonDown(0))
            PlaceObject();

        if (Input.GetMouseButtonDown(1) || Input.GetKeyDown(KeyCode.Escape))
            CancelPlacement();
    }

    public void StartPlacement(InventoryItemData item)
    {
        CancelPlacement();

        currentItem = item;
        ghostObject = Instantiate(item.prefab3D);

        currentRotationY = 0;
        SetGhostMaterial(ghostObject);
    }

    public void StartPlacement(GameObject prefab)
    {
        CancelPlacement();

        currentItem = null; // No item data for custom models
        currentPrefab = prefab;
        ghostObject = Instantiate(prefab);

        currentRotationY = 0;
        SetGhostMaterial(ghostObject);
    }

    void FollowMouse()
    {
        Ray ray = Camera.main.ScreenPointToRay(Input.mousePosition);

        if (Physics.Raycast(ray, out RaycastHit hit, 1000f, groundLayer))
        {
            ghostObject.transform.position = hit.point + Vector3.up * 0.0f;
        }
    }

    void HandleRotation()
    {
        if (Input.GetKey(KeyCode.Q))
            currentRotationY -= rotationSpeed * Time.deltaTime;

        if (Input.GetKey(KeyCode.E))
            currentRotationY += rotationSpeed * Time.deltaTime;

        ghostObject.transform.rotation = Quaternion.Euler(0, currentRotationY, 0);
    }

    void PlaceObject()
    {
        GameObject newObj = Instantiate(currentItem != null ? currentItem.prefab3D : currentPrefab,
            ghostObject.transform.position,
            ghostObject.transform.rotation);

        // Add a component to store the prefab name for save/load
        FurniturePrefabReference prefabRef = newObj.AddComponent<FurniturePrefabReference>();
        prefabRef.prefabPath = currentItem != null ? currentItem.name : currentPrefab.name; // Use the ScriptableObject name or prefab name as the identifier

        // Register the placed object with the FurnitureSaveManager
        FurnitureSaveManager saveManager = FindObjectOfType<FurnitureSaveManager>();
        if (saveManager != null) {
            saveManager.activeFurniture.Add(newObj);
            Debug.Log("Added " + newObj.name + " to activeFurniture list");
        } else {
            Debug.LogWarning("FurnitureSaveManager not found in scene!");
        }

        CancelPlacement();
    }

    void CancelPlacement()
    {
        if (ghostObject != null)
            Destroy(ghostObject);

        ghostObject = null;
        currentItem = null;
        currentPrefab = null;
    }

    void SetGhostMaterial(GameObject obj)
    {
        foreach (Renderer r in obj.GetComponentsInChildren<Renderer>())
            r.material = ghostMaterial;
    }
}
